#!/usr/bin/env python3
"""Canonical lexical inventory of simplification rules in verification.k."""

from __future__ import annotations

import dataclasses
import hashlib
import json
import re
import stat
from dataclasses import dataclass
from pathlib import Path
from typing import Any


_MODULE_NAME_RE = re.compile(
    r"^[ \t]+(?P<name>[A-Za-z][A-Za-z0-9_'-]*)"
    r"(?:[ \t]+\[[^\]\r\n]*\])?[ \t]*$"
)
_TRAILING_ATTRIBUTES_RE = re.compile(
    r"\[(?P<attributes>[^\[\]]*)\][ \t\r\n]*\Z", re.S
)
_CELL_TAG_RE = re.compile(
    r"<(?P<close>/)?(?P<name>[A-Za-z][A-Za-z0-9_'-]*)"
    r"[ \t]*(?P<self_close>/)?>"
)
_OUTER_SENTENCE_KEYWORDS = {
    "imports",
    "syntax",
    "rule",
    "configuration",
    "context",
    "claim",
    "alias",
}


class KRuleInventoryError(RuntimeError):
    """Raised when verification.k cannot produce a canonical inventory."""


@dataclass(frozen=True)
class KRule:
    source_rule_id: str
    module: str
    start_line: int
    end_line: int
    normalized_sha256: str
    attributes: list[str]
    text: str


@dataclass(frozen=True)
class _Sentence:
    keyword: str
    start: int


@dataclass(frozen=True)
class _Module:
    name: str
    content_start: int
    content_end: int
    imports: tuple[str, ...]
    sentences: tuple[_Sentence, ...]


@dataclass(frozen=True)
class _RuleSpan:
    rule: KRule
    start_offset: int
    end_offset: int
    attribute_start: int | None
    attribute_end: int | None


def canonical_json_sha256(document: Any) -> str:
    encoded = json.dumps(
        document,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    ).encode()
    return hashlib.sha256(encoded).hexdigest()


def _mask_non_code(text: str) -> str:
    """Mask comments and string bodies without changing source offsets."""

    output = list(text)
    index = 0
    block_depth = 0
    state = "code"
    while index < len(text):
        character = text[index]
        following = text[index + 1] if index + 1 < len(text) else ""
        if state == "line-comment":
            if character in "\r\n":
                state = "code"
            else:
                output[index] = " "
            index += 1
            continue
        if state == "string":
            if character == "\\" and following:
                output[index] = " "
                output[index + 1] = " "
                index += 2
                continue
            if character == '"':
                state = "code"
            elif character not in "\r\n":
                output[index] = " "
            index += 1
            continue
        if state == "block-comment":
            if character == "/" and following == "*":
                output[index] = output[index + 1] = " "
                block_depth += 1
                index += 2
                continue
            if character == "*" and following == "/":
                output[index] = output[index + 1] = " "
                block_depth -= 1
                index += 2
                if block_depth == 0:
                    state = "code"
                continue
            if character not in "\r\n":
                output[index] = " "
            index += 1
            continue
        if character == "/" and following == "/":
            output[index] = output[index + 1] = " "
            state = "line-comment"
            index += 2
            continue
        if character == "/" and following == "*":
            output[index] = output[index + 1] = " "
            state = "block-comment"
            block_depth = 1
            index += 2
            continue
        if character == '"':
            state = "string"
        index += 1
    return "".join(output)


def _line_ranges(text: str, start: int = 0) -> list[tuple[int, int, int]]:
    ranges: list[tuple[int, int, int]] = []
    line_start = start
    while line_start < len(text):
        newline = text.find("\n", line_start)
        next_start = len(text) if newline < 0 else newline + 1
        line_end = len(text) if newline < 0 else newline
        content_end = (
            line_end - 1
            if line_end > line_start and text[line_end - 1] == "\r"
            else line_end
        )
        ranges.append((line_start, content_end, next_start))
        if newline < 0:
            break
        line_start = next_start
    return ranges


def _line_heads(text: str) -> list[tuple[int, int, str, str]]:
    """Return physical-line word heads without assigning K grammar meaning."""

    heads: list[tuple[int, int, str, str]] = []
    for line_start, content_end, _next_start in _line_ranges(text):
        index = line_start
        while index < content_end and text[index] in " \t":
            index += 1
        word_end = index
        while word_end < content_end and (
            text[word_end].isalnum() or text[word_end] in "_'"
        ):
            word_end += 1
        if word_end > index:
            heads.append(
                (
                    line_start,
                    content_end,
                    text[index:word_end],
                    text[word_end:content_end],
                )
            )
    return heads


def _line_word(line: str) -> tuple[str, str, int]:
    stripped = line.lstrip()
    indent = len(line) - len(stripped)
    word_end = 0
    while word_end < len(stripped) and (
        stripped[word_end].isalnum() or stripped[word_end] in "_'"
    ):
        word_end += 1
    return stripped[:word_end], stripped[word_end:], indent + word_end


def _rule_continuation(line: str) -> tuple[str, int] | None:
    stripped = line.lstrip()
    if stripped.startswith("["):
        return "attributes", len(line) - len(stripped)
    word, rest, word_end = _line_word(line)
    for keyword in ("requires", "ensures"):
        if word == keyword and (
            not rest
            or not (
                rest[0].isalnum()
                or rest[0] in "_'"
            )
        ):
            return keyword, word_end
    return None


def _starts_outer_transition(line: str) -> bool:
    keyword, rest, _word_end = _line_word(line)
    separated = bool(rest) and rest[0] in " \t"
    if keyword == "module":
        return separated and _MODULE_NAME_RE.fullmatch(rest) is not None
    if keyword == "endmodule":
        return not rest.strip()
    if keyword == "rule":
        return separated
    return keyword in _OUTER_SENTENCE_KEYWORDS and separated


def _terminal_attribute_line(line: str) -> bool:
    match = _TRAILING_ATTRIBUTES_RE.search(line)
    if match is None:
        return False
    start = match.start()
    return start == 0 or line[start - 1].isspace()


def _scan_rule_delimiters(
    line: str,
    delimiters: list[str],
) -> None:
    closing = {")": "(", "]": "[", "}": "{"}
    index = 0
    while index < len(line):
        if line[index] == "<":
            cell = _CELL_TAG_RE.match(line, index)
            if cell is not None:
                marker = f"<{cell.group('name')}>"
                if cell.group("close"):
                    if delimiters and delimiters[-1] == marker:
                        delimiters.pop()
                elif not cell.group("self_close"):
                    delimiters.append(marker)
                index = cell.end()
                continue
        character = line[index]
        if character in "([{":
            delimiters.append(character)
        elif character in closing:
            if delimiters and delimiters[-1] == closing[character]:
                delimiters.pop()
        index += 1


def _rule_bubble_end(masked_text: str, start: int) -> int:
    """Find when an outer rule bubble returns control to outer parsing."""

    seen_rewrite = False
    clause_has_content = False
    candidate_end: int | None = None
    delimiters: list[str] = []
    ranges = _line_ranges(masked_text, start)
    for line_start, line_end, next_start in ranges:
        line = masked_text[line_start:line_end]
        if not line.strip():
            continue

        continuation = (
            _rule_continuation(line)
            if seen_rewrite and candidate_end is not None
            else None
        )
        if candidate_end is not None:
            if continuation is None and _starts_outer_transition(line):
                return candidate_end
            candidate_end = None

        content_start = 0
        if continuation is not None:
            kind, content_start = continuation
            if kind in {"requires", "ensures"}:
                clause_has_content = False

        if not seen_rewrite:
            rewrite = line.find("=>")
            if rewrite >= 0:
                seen_rewrite = True
                content_start = rewrite + 2
            else:
                content_start = len(line)

        _scan_rule_delimiters(line, delimiters)
        if seen_rewrite and line[content_start:].strip():
            clause_has_content = True

        if (
            seen_rewrite
            and clause_has_content
            and not delimiters
            and _terminal_attribute_line(line)
        ):
            return next_start
        if seen_rewrite and clause_has_content and not delimiters:
            candidate_end = next_start
    if candidate_end is not None:
        return candidate_end
#!/usr/bin/env python3
"""Hard, model-free sanity gate for a deterministic Klean generation."""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable

REPO = Path(__file__).resolve().parent.parent
if str(REPO) not in sys.path:
    sys.path.insert(0, str(REPO))

from tools import klean_export
from tools import lemma_discovery_contract


class KleanPreflightError(RuntimeError):
    pass


_SIDECAR_NAMES = (
    "input-manifest.json",
    "generator-manifest.json",
    "trust-inventory.json",
    "export-result.json",
)


@dataclass(frozen=True)
class PreflightSnapshot:
    stage1_workspace_sha256: str
    stage3_discovery_manifest_sha256: str
    generated_tree_sha256: str
    sidecar_sha256: tuple[tuple[str, str], ...]


def _preflight_snapshot(
    frozen_input: Path,
    discovery_manifest: Path,
    generation: Path,
) -> PreflightSnapshot:
    generated = generation / "generated"
    try:
        sidecars = tuple(
            (
                name,
                hashlib.sha256(
                    pipeline_path.read_bytes()
                ).hexdigest(),
            )
            for name in _SIDECAR_NAMES
            if (
                pipeline_path := generation / name
            ).is_file()
            and not pipeline_path.is_symlink()
        )
        if len(sidecars) != len(_SIDECAR_NAMES):
            raise KleanPreflightError(
                "preflight sidecar set is incomplete or unsafe"
            )
        return PreflightSnapshot(
            stage1_workspace_sha256=klean_export.tree_digest(
                frozen_input
            ),
            stage3_discovery_manifest_sha256=hashlib.sha256(
                discovery_manifest.read_bytes()
            ).hexdigest(),
            generated_tree_sha256=klean_export.tree_digest(generated),
            sidecar_sha256=sidecars,
        )
    except (OSError, klean_export.KleanExportError) as error:
        raise KleanPreflightError(
            "cannot snapshot immutable preflight inputs"
        ) from error


def _require_unchanged_snapshot(
    expected: PreflightSnapshot,
    frozen_input: Path,
    discovery_manifest: Path,
    generation: Path,
) -> None:
    current = _preflight_snapshot(
        frozen_input, discovery_manifest, generation
    )
    if current.stage1_workspace_sha256 != (
        expected.stage1_workspace_sha256
    ):
        raise KleanPreflightError(
            "frozen Stage 1 input changed during preflight"
        )
    if current.stage3_discovery_manifest_sha256 != (
        expected.stage3_discovery_manifest_sha256
    ):
        raise KleanPreflightError(
            "validated Stage 3 discovery manifest changed during preflight"
        )
    if current.generated_tree_sha256 != expected.generated_tree_sha256:
        raise KleanPreflightError(
            "generated project changed during preflight"
        )
    if current.sidecar_sha256 != expected.sidecar_sha256:
        raise KleanPreflightError(
            "generation sidecar changed during preflight"
        )


def _regular_json(path: Path, label: str) -> dict[str, Any]:
    if not path.is_file() or path.is_symlink():
        raise KleanPreflightError(f"{label} must be a regular file: {path}")
    try:
        document = json.loads(path.read_text())
    except (OSError, ValueError) as error:
        raise KleanPreflightError(f"{label} is malformed: {path}") from error
    if not isinstance(document, dict):
        raise KleanPreflightError(f"{label} must be a JSON object")
    return document


def _run(
    command: list[str],
    *,
    cwd: Path,
    timeout: int,
) -> tuple[int, str]:
    try:
        result = subprocess.run(
            command,
            cwd=cwd,
            timeout=timeout,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
        )
        return result.returncode, result.stdout
    except subprocess.TimeoutExpired:
        return 124, f"TIMEOUT after {timeout}s"


def _lean_sources(generated: Path) -> list[Path]:
    return [
        path
        for _relative, kind, path in klean_export._tree_entries(generated)
        if kind == "file" and path.suffix == ".lean"
    ]


def _trust_declarations(sources: list[Path]) -> dict[str, tuple[str, str]]:
    declarations: dict[str, tuple[str, str]] = {}
    for source in sources:
        for declaration in klean_export.lean_trust_declarations(source):
            name = declaration["name"]
            if name in declarations:
                raise KleanPreflightError(
                    f"duplicate trust declaration: {name}"
                )
            declarations[name] = (
                declaration["kind"],
                declaration["type"],
            )
    return declarations


def _reject_proposition_trust(
    generated: Path,
    sources: list[Path],
    declarations: dict[str, tuple[str, str]],
) -> None:
    """Apply a policy that is independent of the generator's allowlist.

    Generated executable constants may remain opaque at the Klean boundary,
    but generated propositions/proofs may never be assumed.  In particular,
    the immutable target module must contain only a proposition definition,
    never an axiom or opaque proof.
    """

    for source in sources:
        relative = source.relative_to(generated).as_posix()
        if source.name == "Lemmas.lean" and re.search(
            r"(?m)^\s*(?:axiom|opaque)\s+", source.read_text()
        ):
            raise KleanPreflightError(
                f"proposition trust is forbidden in {relative}"
            )
    for name, (_kind, lean_type) in declarations.items():
        normalized = " ".join(lean_type.split())
        proposition_like = (
            normalized in {"Prop", "True", "False"}
            or " Prop" in f" {normalized}"
            or re.search(r":\s*Prop(?:\s|$)", normalized) is not None
            or normalized.startswith(("∀ ", "∃ "))
            or re.search(r"(^|[ (])(?:True|False)(?:$|[ )])", normalized)
            is not None
            or re.search(r"(?:^| )[^ ]+\s*=\s*[^ ]+", normalized) is not None
        )
        if proposition_like:
            raise KleanPreflightError(
                f"proposition trust is forbidden for {name}: {lean_type}"
            )


def _source_and_obligation_gate(
    frozen_input: Path,
    discovery_manifest: Path,
    generated: Path,
    input_manifest: dict[str, Any],
    generator_manifest: dict[str, Any],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    verification = frozen_input / "verification.k"
    if not verification.is_file() or verification.is_symlink():
        raise KleanPreflightError("frozen input is missing regular verification.k")
    try:
        validated = lemma_discovery_contract.validate_trust_boundary(
            frozen_input, discovery_manifest
        )
    except lemma_discovery_contract.LemmaDiscoveryContractError as error:
        raise KleanPreflightError(str(error)) from error
    discovery_hash = hashlib.sha256(discovery_manifest.read_bytes()).hexdigest()
    if input_manifest.get("inventory_sha256") != validated[
        "inventory_sha256"
    ]:
        raise KleanPreflightError(
            "Stage 1/Stage 3 inventory hash changed after deterministic export"
        )
    source_rules = klean_export._domain_source_rules(
        validated, discovery_hash
    )
    if input_manifest.get("source_rules") != source_rules:
        raise KleanPreflightError(
            "Stage 3 DOMAIN_LEMMA inventory changed after deterministic export"
        )
    if input_manifest.get("verification_sha256") != hashlib.sha256(
        verification.read_bytes()
    ).hexdigest():
        raise KleanPreflightError("verification.k hash changed after export")

    mapping_path = generated / "obligation-map.json"
    obligation_map = _regular_json(mapping_path, "obligation map")
    if obligation_map.get("source_rules") != source_rules:
        raise KleanPreflightError(
            "source rules and generated obligations are not bijective"
        )
    obligations = obligation_map.get("obligations")
    if not isinstance(obligations, list):
        raise KleanPreflightError("generated obligation list is malformed")
    eligible = source_rules
    expected_ids = [rule["source_rule_id"] for rule in eligible]
    observed_ids: list[str] = []
    for obligation in obligations:
        if not isinstance(obligation, dict):
            raise KleanPreflightError("generated obligation is malformed")
        source_rule_id = obligation.get("source_rule_id")
        if not isinstance(source_rule_id, str):
            raise KleanPreflightError("generated obligation ID is malformed")
        observed_ids.append(source_rule_id)
        lean_conjunct = obligation.get("lean_conjunct")
        if not isinstance(lean_conjunct, str) or not lean_conjunct:
            raise KleanPreflightError("generated Lean conjunct is malformed")
        if obligation.get("lean_conjunct_sha256") != klean_export.sha256_text(
            lean_conjunct
        ):
            raise KleanPreflightError("generated Lean conjunct hash changed")
        source_rule = eligible[len(observed_ids) - 1] if len(
            observed_ids
        ) <= len(eligible) else None
        if source_rule is None or obligation.get("source_span") != {
            "start_line": source_rule["start_line"],
            "end_line": source_rule["end_line"],
        }:
            raise KleanPreflightError(
                "source rules and generated obligations are not bijective"
            )
        for key in (
            "normalized_sha256",
            "inventory_sha256",
            "discovery_manifest_sha256",
        ):
            if obligation.get(key) != source_rule[key]:
                raise KleanPreflightError(
                    "generated obligation provenance differs from "
                    f"Stage 1/Stage 3: {key}"
                )
    if observed_ids != expected_ids or len(set(observed_ids)) != len(
        observed_ids
    ):
        raise KleanPreflightError(
            "source rules and generated obligations are not bijective"
        )
    parameters = obligation_map.get("trust_parameters")
    if not isinstance(parameters, list):
        raise KleanPreflightError("generated trust-parameter list is malformed")
    validate_trust_parameter_links(expected_ids, parameters)
    if generator_manifest.get("obligation_count") != len(obligations):
        raise KleanPreflightError("generator obligation count changed")
    if generator_manifest.get("obligation_map_sha256") != hashlib.sha256(
        mapping_path.read_bytes()
    ).hexdigest():
        raise KleanPreflightError("generated obligation map hash changed")
    expected_definition = klean_export.expected_target_definition(
        obligation_map
    )
    try:
        target = klean_export.target_statement(generated)
    except klean_export.KleanExportError as error:
        raise KleanPreflightError(str(error)) from error
    if expected_definition is None:
        if target is not None:
            raise KleanPreflightError(
                "zero obligations unexpectedly generated a target proposition"
            )
    elif (
        target is None
        or target.get("definition_sha256")
        != klean_export.sha256_text(expected_definition)
    ):
        raise KleanPreflightError(
            "generated target is not the exact conjunction of mapped obligations"
        )
    return source_rules, obligations


def validate_trust_parameter_links(
    expected_ids: list[str], parameters: list[object]
) -> set[str]:
    """Validate every opaque parameter without requiring one per theorem."""

    bound_rule_ids: set[str] = set()
    for parameter in parameters:
        if not isinstance(parameter, dict):
            raise KleanPreflightError("generated trust parameter is malformed")
        source_rule_ids = parameter.get("source_rule_ids")
        if (
            not isinstance(source_rule_ids, list)
            or not source_rule_ids
            or not all(
                isinstance(source_rule_id, str)
                and source_rule_id in expected_ids
                for source_rule_id in source_rule_ids
            )
        ):
            raise KleanPreflightError(
                "trust parameter is not bound to source obligations"
            )
        bound_rule_ids.update(source_rule_ids)
    return bound_rule_ids


def _check_imports(generated: Path, sources: list[Path]) -> None:
    for source in sources:
        for line in source.read_text().splitlines():
            stripped = line.strip()
            if not stripped.startswith("import "):
                continue
            imported = stripped.removeprefix("import ").strip()
            if (
                not imported
                or imported.startswith(("/", "."))
                or ".." in imported
                or '"' in imported
                or "\\" in imported
            ):
                raise KleanPreflightError(
                    f"untrusted Lean import in {source}: {imported!r}"
                )
    for name in ("lakefile.toml", "lakefile.lean", "lean-toolchain"):
        path = generated / name
        if path.exists() and (not path.is_file() or path.is_symlink()):
            raise KleanPreflightError(
                f"generated dependency metadata is not regular: {path}"
            )
        if path.is_file():
            text = path.read_text()
            if re.search(r"(?m)^\s*(?:path|dir)\s*=\s*\"/", text):
                raise KleanPreflightError(
                    f"absolute dependency path in generated {name}"
                )


def check_generation(
    frozen_input: Path,
    discovery_manifest: Path,
    generation: Path,
    *,
    toolchain_lock: Path,
    run_command: Callable[..., tuple[int, str]] = _run,
) -> dict[str, Any]:
    frozen_input = Path(frozen_input)
    discovery_manifest = Path(discovery_manifest)
    generation = Path(generation)
    generated = generation / "generated"
    if not frozen_input.is_dir() or frozen_input.is_symlink():
        raise KleanPreflightError("frozen K input must be a real directory")
    if not discovery_manifest.is_file() or discovery_manifest.is_symlink():
        raise KleanPreflightError(
            "validated Stage 3 discovery manifest must be a regular file"
        )
    if not generation.is_dir() or generation.is_symlink():
        raise KleanPreflightError("generation must be a real directory")
    if not generated.is_dir() or generated.is_symlink():
        raise KleanPreflightError("generated project must be a real directory")
    # Traversing every entry rejects symlinks/FIFOs before any build command.
    klean_export._tree_entries(generated)
    snapshot = _preflight_snapshot(
        frozen_input, discovery_manifest, generation
    )
    input_manifest = _regular_json(
        generation / "input-manifest.json", "input manifest"
    )
    generator_manifest = _regular_json(
        generation / "generator-manifest.json", "generator manifest"
#!/usr/bin/env python3
"""Validate Stage 3 classifications against the canonical K rule inventory."""

from __future__ import annotations

import json
import stat
from pathlib import Path
from typing import Any

from tools.k_rule_inventory import KRuleInventoryError, inventory_verification


_MANIFEST_KEYS = {"schema_version", "inventory_sha256", "rules"}
_RULE_KEYS = {"source_rule_id", "classification", "rationale"}
_CLASSIFICATIONS = {
    "DEFINITION",
    "OPERATIONAL_RULE",
    "PROVED_DERIVED_LEMMA",
    "DOMAIN_LEMMA",
}


class LemmaDiscoveryContractError(RuntimeError):
    """Raised when a Stage 3 manifest crosses its trust boundary."""


def _regular_json(path: Path) -> dict[str, Any]:
    path = Path(path)
    try:
        mode = path.stat(follow_symlinks=False).st_mode
    except OSError as error:
        raise LemmaDiscoveryContractError(
            f"lemma discovery manifest must be a regular file: {path}"
        ) from error
    if not stat.S_ISREG(mode):
        raise LemmaDiscoveryContractError(
            f"lemma discovery manifest must be a regular file: {path}"
        )
    try:
        document = json.loads(path.read_bytes())
    except (OSError, UnicodeError, ValueError) as error:
        raise LemmaDiscoveryContractError(
            f"lemma discovery manifest is malformed: {path}"
        ) from error
    if not isinstance(document, dict):
        raise LemmaDiscoveryContractError(
            "lemma discovery manifest must be a JSON object"
        )
    return document


def _exact_keys(
    document: dict[str, Any], expected: set[str], label: str
) -> None:
    unexpected = sorted(set(document) - expected)
    if unexpected:
        raise LemmaDiscoveryContractError(
            f"{label} has unexpected key: {unexpected[0]}"
        )
    missing = sorted(expected - set(document))
    if missing:
        raise LemmaDiscoveryContractError(
            f"{label} is missing key: {missing[0]}"
        )


def validate_trust_boundary(
    workspace: Path, manifest: Path
) -> dict[str, Any]:
    try:
        inventory = inventory_verification(Path(workspace))
    except KRuleInventoryError as error:
        raise LemmaDiscoveryContractError(str(error)) from error
    document = _regular_json(Path(manifest))
    _exact_keys(document, _MANIFEST_KEYS, "lemma discovery manifest")
    schema_version = document["schema_version"]
    if (
        not isinstance(schema_version, int)
        or isinstance(schema_version, bool)
        or schema_version != 2
    ):
        raise LemmaDiscoveryContractError(
            "lemma discovery schema_version must be 2"
        )
    if document["inventory_sha256"] != inventory["inventory_sha256"]:
        raise LemmaDiscoveryContractError(
            "lemma discovery inventory_sha256 does not match canonical inventory"
        )
    entries = document["rules"]
    if not isinstance(entries, list):
        raise LemmaDiscoveryContractError(
            "lemma discovery rules must be a JSON list"
        )
    canonical_rules = inventory["rules"]
    canonical_by_id = {
        rule["source_rule_id"]: rule for rule in canonical_rules
    }
    classified_by_id: dict[str, dict[str, str]] = {}
    for index, entry in enumerate(entries):
        label = f"lemma discovery rule {index}"
        if not isinstance(entry, dict):
            raise LemmaDiscoveryContractError(f"{label} must be an object")
        _exact_keys(entry, _RULE_KEYS, label)
        source_rule_id = entry["source_rule_id"]
        if not isinstance(source_rule_id, str) or not source_rule_id:
            raise LemmaDiscoveryContractError(
                f"{label} source_rule_id must be a nonempty string"
            )
        if source_rule_id in classified_by_id:
            raise LemmaDiscoveryContractError(
                f"duplicate lemma discovery source_rule_id: {source_rule_id}"
            )
        if source_rule_id not in canonical_by_id:
            raise LemmaDiscoveryContractError(
                f"unknown lemma discovery source_rule_id: {source_rule_id}"
            )
        classification = entry["classification"]
        if (
            not isinstance(classification, str)
            or classification not in _CLASSIFICATIONS
        ):
            raise LemmaDiscoveryContractError(
                f"{label} classification must be DEFINITION, "
                "OPERATIONAL_RULE, PROVED_DERIVED_LEMMA, or DOMAIN_LEMMA"
            )
        canonical_rule = canonical_by_id[source_rule_id]
        if (
            "simplification" in canonical_rule["attributes"]
            and classification
            in {"OPERATIONAL_RULE", "PROVED_DERIVED_LEMMA"}
        ):
            raise LemmaDiscoveryContractError(
                f"{label} simplification rule must be classified as "
                "DEFINITION or DOMAIN_LEMMA"
            )
        rationale = entry["rationale"]
        if not isinstance(rationale, str) or not rationale.strip():
            raise LemmaDiscoveryContractError(
                f"{label} rationale must be a nonempty string"
            )
        classified_by_id[source_rule_id] = {
            "classification": classification,
            "rationale": rationale,
        }
    missing = [
        rule["source_rule_id"]
        for rule in canonical_rules
        if rule["source_rule_id"] not in classified_by_id
    ]
    if missing:
        raise LemmaDiscoveryContractError(
            f"lemma discovery manifest is missing source_rule_id: {missing[0]}"
        )
    definitions: list[dict[str, Any]] = []
    operational_rules: list[dict[str, Any]] = []
    proved_derived_lemmas: list[dict[str, Any]] = []
    domain_lemmas: list[dict[str, Any]] = []
    for rule in canonical_rules:
        classification = classified_by_id[rule["source_rule_id"]]
        classified_rule = {**rule, **classification}
        role = classification["classification"]
        if role == "DEFINITION":
            definitions.append(classified_rule)
        elif role == "OPERATIONAL_RULE":
            operational_rules.append(classified_rule)
        elif role == "PROVED_DERIVED_LEMMA":
            proved_derived_lemmas.append(classified_rule)
        else:
            domain_lemmas.append(classified_rule)
    return {
        **inventory,
        "definitions": definitions,
        "operational_rules": operational_rules,
        "proved_derived_lemmas": proved_derived_lemmas,
        "domain_lemmas": domain_lemmas,
    }
